def read(p):
    return json.loads(Path(p).read_text())

def write(p, d):
    p = Path(p); p.parent.mkdir(parents=True, exist_ok=True)
    q = p.with_suffix(p.suffix + '.tmp')
    q.write_text(json.dumps(d, ensure_ascii=False, indent=2, allow_nan=False) + '\n')
    q.replace(p)

def fingerprint(p):
    p = Path(p)
    with p.open('rb') as f:
        sha = hashlib.file_digest(f, 'sha256').hexdigest()
    return {'path': str(p.relative_to(ROOT)) if p.is_relative_to(ROOT) else str(p), 'sha256': sha, 'size': p.stat().st_size}

def check_receipt(r):
    p = Path(r['path']); p = p if p.is_absolute() else ROOT / p
    actual = fingerprint(p)
    if (actual['sha256'], actual['size']) != (r['sha256'], r['size']):
        raise ValueError(f'input drift: {p}')

def check_launch():
    from backtest.scripts.maintenance.experiment_harness import inspect_state
    parent = inspect_state(BASE/'docs/harness-state.json', check_drift=False)
    assert parent['status'] == 'closed'
    state = read(STATE); plan = read(PLAN)
    check_receipt(state['plan'])
    if time.time() >= state['deadline']: raise RuntimeError('wall budget exhausted')
    if any(j['status'] == 'running' for j in state['jobs']): raise RuntimeError('job already running')
    for r in plan['frozen_files']: check_receipt(r)
    if state['model_fits_started'] >= plan['budget']['max_model_fits']: raise RuntimeError('fit budget exhausted')
    return state, plan

def register_adapter(path):
    p=Path(path)
    receipt = BASE/'docs'/f'{PREFIX}-adapter-{p.stem}.json'
    doc={'source':fingerprint(p), 'source_text':p.read_text(), 'purpose':'Exact task adapter source retained as audit evidence; executable temporary source is removed at closure.'}
    if receipt.exists() and read(receipt)!=doc: raise RuntimeError('adapter already frozen with different bytes')
    write(receipt, doc)
    return fingerprint(receipt)
